import json, re
from pathlib import Path
from orca_task_sdk import run_orca

receipt = run_orca("job.inp", dependencies=("ethanol.xyz",), request_key="ethanol_optfreq")
files = receipt.get("files", {}) or {}

def read(path):
    try:
        return Path(path).read_text(encoding="utf-8", errors="replace")
    except Exception:
        return ""

def choose(pred):
    for k in files:
        if pred(k):
            return k
    return None

xyz_key = choose(lambda k: k.lower().endswith(".xyz"))
out_key = choose(lambda k: "stdout" in k.lower())

def parse_xyz(path):
    lines = read(path).splitlines()
    for i, line in enumerate(lines):
        s = line.strip()
        if s.isdigit():
            n = int(s)
            if i + 2 + n <= len(lines):
                atoms = []
                ok = True
                for j in range(i + 2, i + 2 + n):
                    p = lines[j].split()
                    if len(p) < 4:
                        ok = False
                        break
                    try:
                        atoms.append({"element": p[0], "x": float(p[1]), "y": float(p[2]), "z": float(p[3])})
                    except Exception:
                        ok = False
                        break
                if ok and atoms:
                    return atoms
    return None

def parse_freqs(text):
    vals = []
    pat = re.compile(r"^\s*(\d+):\s+(-?\d+(?:\.\d+)?)\s+cm\*\*-1")
    for line in text.splitlines():
        m = pat.match(line)
        if m:
            v = float(m.group(2))
            if abs(v) > 1e-8:
                vals.append(v)
    return vals

xyz_atoms = parse_xyz(files.get(xyz_key)) if xyz_key else None
freqs = parse_freqs(read(files.get(out_key))) if out_key else []

obs = []
if xyz_atoms:
    obs.append({"name": "optimized_geometry", "value": xyz_atoms, "unit": "angstrom", "sources": [{"internal_request_key": receipt.get("request_key"), "filename": xyz_key, "location": None}], "limitations": ["Geometry parsed from ORCA Opt+Freq output; scientific qualification is not implied."]})
if freqs:
    obs.append({"name": "vibrational_frequencies", "value": freqs, "unit": "cm^-1", "sources": [{"internal_request_key": receipt.get("request_key"), "filename": out_key, "location": "VIBRATIONAL FREQUENCIES"}], "limitations": ["Frequencies parsed from ORCA output; imaginary modes or convergence should be reviewed."]})
Path("observations.json").write_text(json.dumps({"version": 1, "observations": obs}, indent=2), encoding="utf-8")

result = {"request_key": receipt.get("request_key"), "input_fingerprint": receipt.get("input_fingerprint"), "operation_status": receipt.get("operation_status"), "scientific_validation": receipt.get("scientific_validation"), "actual_conditions": receipt.get("actual_conditions"), "files": files}
